type TranslationRecord = Record<string, unknown>;
function mergeTranslation(target: TranslationRecord, source: TranslationRecord): void {
  for (const [key, value] of Object.entries(source)) {
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      const current = target[key];
      const nested = current && typeof current === 'object' && !Array.isArray(current) ? current as TranslationRecord : {};
      target[key] = nested;
      mergeTranslation(nested, value as TranslationRecord);
    } else {
      target[key] = value;
    }
  }
}
function mergeLocale(language: string, bundle: TranslationRecord): void {
  const translation = resources[language as keyof typeof resources].translation as TranslationRecord;
  mergeTranslation(translation, bundle);
}

